GSM_st.name='GSM'; 
GSM_st.lat=35.63;
GSM_st.lon=-83.94;
GSM_st.alt=810;
GSM_st.env='con';
GSM_st.footp='F';
%%
GSM_rd=read_betsy('GSM_head',GSM_st.name);
%%
datevec(GSM_rd.Time(1)) %[output:1658fbb2]
datevec(GSM_rd.Time(end)) %[output:343f51a0]
prctile(GSM_rd.U_S,[5, 50, 95]) %[output:25ac41c0]
plotFigControl(GSM_rd,GSM_st.name); %[output:29ce3544] %[output:27bcab9f] %[output:05f01119] %[output:8d79e754] %[output:18f3d87b] %[output:225e3ca1] %[output:2235bb4f] %[output:39876bb0] %[output:59cc1589]
% 1 size cut, 
% sc: ok, clear seasonal cycle, max in summer, some negatives
%[text] lambdaSC=\[450;550;700\]\*ones(1,4); lambdaAE3=\[467;530;660\]\*ones(1,4); lambdaAE7=\[370 470 520 590 660 880 950\]; GSM\_cal=compute\_exp\_SSA(GSM\_rd,lambdaSC, lambdaAE3); plotFigControl\_cal(GSM\_cal, GSM\_st.name);
%%
%Questions:
%problems:

%instrumental change in June 2015 ? seems to have a rupture October 2015
%%
GSM_tr=GSM_rd;
GSM_tr.y=year(GSM_tr.Time);
%eneleve une valeur de 2019
GSM_tr=GSM_tr(1:end-1,:);
% begin at the beginning of a year:1994
%end year: 2014
P=timerange('1994-01-01','2019-01-01');
GSM_tr=GSM_tr(P,:);

names=fieldnames(GSM_tr);
c= startsWith(names,["T1";"T0";"T_";"P_";"P1_";"P0_"]) | endsWith(names,'T');
N=names(c);
for i=1:length(N)
    GSM_tr.(N{i})=[];
end

P2=timerange('2014-05-01','2014-10-31');
GSM_tr.BsG_S(P2)=NaN;

% dry: very low data coverage in end summer autumn
%otherwise seems ok
%%
GSM_result= all_trend_STN(GSM_tr,GSM_st); 
%%
GSM_result_D=GSM_result;

